#!/bin/bash

# Check if the directory exists
if [ ! -d "/srv/www" ]; then
    echo "Directory /srv/www does not exist."
    exit 1
fi

# Check permissions of directories
find /srv/www -type d -exec test $(stat -c %a {} | cut -c1-3) -eq 755 \; -print | grep -v '^$' || {
    echo "Not all directories have 755 permissions."
    exit 1
}

# Check permissions of regular files
find /srv/www -type f ! -name "*.sh" -exec test $(stat -c %a {}) -eq 644 \; -print | grep -v '^$' || {
    echo "Not all regular files have 644 permissions."
    exit 1
}

# Check permissions of .sh files
find /srv/www -type f -name "*.sh" -exec test $(stat -c %a {}) -eq 755 \; -print | grep -v '^$' || {
    echo "Not all .sh files have 755 permissions."
    exit 1
}

# Check owners (should not change)
original_owner=$(stat -c %u:%g /srv/www)
find /srv/www -user $(echo $original_owner | cut -d: -f1) -group $(echo $original_owner | cut -d: -f2) | grep -v '^$' || {
    echo "Ownership has changed."
    exit 1
}

echo "All checks passed successfully."
exit 0

#!/bin/bash

# Проверяем права на каталог /srv/www и его содержимое
if [ ! -d /srv/www ]; then
  echo "Каталог /srv/www не существует."
  exit 1
fi

# Функция для проверки прав каталогов
check_dirs() {
  local dir="$1"
  find "$dir" -type d -exec test -perm 755 {} \; -print || {
    echo "Неправильные права для каталога: {}"
    exit 1
  }
}

# Функция для проверки прав обычных файлов
check_files() {
  local dir="$1"
  find "$dir" -type f ! -name "*.sh" -exec test -perm 644 {} \; -print || {
    echo "Неправильные права для файла: {}"
    exit 1
  }
}

# Функция для проверки прав файлов с расширением .sh
check_sh_files() {
  local dir="$1"
  find "$dir" -type f -name "*.sh" -exec test -perm 755 {} \; -print || {
    echo "Неправильные права для файла: {}"
    exit 1
  }
}

# Проверяем все подкаталоги и файлы
check_dirs /srv/www
check_files /srv/www
check_sh_files /srv/www

# Если все проверки прошли успешно
echo "Права в каталоге /srv/www установлены правильно."
exit 0

